-- Run only after mapping dealer/company/distributor IDs to the existing platform.
create table if not exists public.dealer_settings(id uuid primary key default gen_random_uuid(),dealer_id uuid unique not null,showroom_name text,business_name text,address jsonb not null default '{}'::jsonb,gstin text,pan text,contact_person text,mobile text,whatsapp text,email text,logo_path text,invoice_footer text,terms_conditions text,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.customers(id uuid primary key default gen_random_uuid(),dealer_id uuid not null,name text not null,mobile text not null,whatsapp text,email text,gender text,billing_address jsonb not null default '{}'::jsonb,shipping_address jsonb not null default '{}'::jsonb,gstin text,pan text,custom_data jsonb not null default '{}'::jsonb,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.dealer_inventory(id uuid primary key default gen_random_uuid(),dealer_id uuid not null,distributor_id uuid,vehicle_id uuid,vin text unique,chassis_number text unique,motor_number text,battery_number text,controller_number text,charger_number text,model text not null,variant text,color text,mrp numeric(14,2) not null default 0,status inventory_status not null default 'AVAILABLE',reserved_by uuid references auth.users(id),reserved_until timestamptz,received_at timestamptz,sold_at timestamptz,custom_data jsonb not null default '{}'::jsonb);
create table if not exists public.invoices(id uuid primary key default gen_random_uuid(),invoice_number text unique not null,dealer_id uuid not null,distributor_id uuid,company_id uuid,customer_id uuid references public.customers(id),invoice_date timestamptz not null default now(),subtotal numeric(14,2) not null,discount numeric(14,2) not null default 0,taxable_amount numeric(14,2) not null,cgst_amount numeric(14,2) not null,sgst_amount numeric(14,2) not null,gst_amount numeric(14,2) not null,grand_total numeric(14,2) not null,amount_paid numeric(14,2) not null default 0,payment_status text,payment_method text,payment_reference text,status invoice_status not null default 'DRAFT',pdf_storage_path text,created_by uuid references auth.users(id),dealer_snapshot jsonb not null,customer_snapshot jsonb not null,financial_snapshot jsonb not null,created_at timestamptz default now(),updated_at timestamptz default now());
create table if not exists public.invoice_items(id uuid primary key default gen_random_uuid(),invoice_id uuid not null references public.invoices(id),inventory_id uuid references public.dealer_inventory(id),vehicle_id uuid,description text,model text,variant text,vin text,chassis_number text,motor_number text,battery_number text,quantity numeric(10,2) not null default 1,mrp numeric(14,2) not null,discount numeric(14,2) not null default 0,taxable_amount numeric(14,2) not null,cgst numeric(14,2) not null,sgst numeric(14,2) not null,total numeric(14,2) not null,vehicle_snapshot jsonb not null default '{}'::jsonb);
create index if not exists customers_dealer_idx on public.customers(dealer_id);create index if not exists inventory_dealer_status_idx on public.dealer_inventory(dealer_id,status);create index if not exists invoices_dealer_date_idx on public.invoices(dealer_id,invoice_date desc);
alter table public.dealer_settings enable row level security;alter table public.customers enable row level security;alter table public.dealer_inventory enable row level security;alter table public.invoices enable row level security;alter table public.invoice_items enable row level security;
